</div><footer><span>HushHawk Property Intelligence │ HushHawk │ Built for a Bigger Tomorrow.</span><span>JACKSONVILLE · PEOPLE · PROPERTIES · PROSPERITY</span></footer></main>
<div v-if="dialog" class="modal-backdrop" @click.self="closeDialog" @keydown="dialogKeys"><section ref="dialogEl" class="dialog" role="dialog" aria-modal="true" :aria-labelledby="uid+'-title'" tabindex="-1"><button class="dialog-close" @click="closeDialog" aria-label="Close dialog">×</button><h2 :id="uid+'-title'">{{dialogTitle}}</h2>
<template v-if="dialog==='import'"><p>Preview a {{county}} County CSV in this page session. It will not be saved to your CRM or sent to Podio.</p><p>Required column: <b>address</b>. Optional: city, owner, ownerType, type, value, tags (semicolon separated), last, status.</p><label>Choose CSV<input type="file" accept=".csv,text/csv" @change="readCsv" :disabled="isEditing||importBusy"></label><p role="status">{{importBusy?'Reading CSV…':importNotice}}</p><p role="alert">{{importError}}</p><button class="gold action" @click="loadCsv" :disabled="!pendingRows.length||importBusy">Load {{pendingRows.length}} Preview Records</button><p>Maximum 1 MB / 5,000 rows. No live county provider is connected.</p></template>
<template v-else-if="dialog==='columns'"><label class="column-check" v-for="c in columns" :key="c.key"><input type="checkbox" v-model="visibleColumns" :value="c.key" :disabled="c.key==='address'">{{c.label}}</label></template>
<template v-else-if="dialog==='thread'"><p>{{imported||county!=='Duval'?'No connected conversation is available.':'Active conversation for '+(selectedRecord?.address||'4521 Lenox Ave')}}</p><label>Message draft<textarea v-model="draft"></textarea></label><button class="gold action" @click="saveDraft">Save Draft</button><p role="status">{{draftNotice}}</p></template>
