<template v-else-if="dialog==='campaign'&&focusedCampaign"><h3>{{focusedCampaign.name}}</h3><div class="campaign-summary"><div><b>{{focusedCampaign.sent}}</b>Sent</div><div><b>{{focusedCampaign.open}}</b>Opened</div><div><b>{{focusedCampaign.reply}}</b>Replied</div><div><b>{{focusedCampaign.leads}}</b>Leads</div></div><p>Direct mail & email campaign configured.</p></template>
<template v-else><p>County provider and messaging connections are pending.</p><a href="/settings" @click="guard">Open Settings →</a></template>
</section></div></section></template>

<script>
import {ref,computed,watch,nextTick} from 'vue';
import Papa from 'papaparse';
import {navigation,iconDefaults,sampleRecords,floridaGeometry} from './data.js';
export default {props:{uid:{type:String,required:true},content:{type:Object,required:true},},setup(props){
const isEditing=computed(()=>{return false;});
const icons=ref({}),{getIcon}=wwLib.useIcons();watch(()=>Object.keys(iconDefaults).map(k=>props.content?.[k+'Icon']||iconDefaults[k]),async names=>{const h=await Promise.all(names.map(n=>getIcon(n).catch(()=>'')));icons.value=Object.fromEntries(Object.keys(iconDefaults).map((k,i)=>[k,h[i]]));},{immediate:true});
const navOpen=ref(false),query=ref(''),county=ref('Duval'),records=ref(sampleRecords.map(r=>({...r,tags:[...r.tags]}))),imported=ref(false),checked=ref([]),sort=ref('reference'),selectedId=ref(''),pendingFilters=ref(['Absentee','Probate','Tax Delinquent','Vacant','High Equity']),applied=ref([]),notice=ref(''),draft=ref(''),draftNotice=ref(''),dialog=ref(''),dialogEl=ref(null),importBusy=ref(false),importNotice=ref(''),importError=ref(''),pendingRows=ref([]),focusedCampaign=ref(null);
const columns=[['address','Address'],['city','City'],['owner','Owner Name'],['ownerType','Owner Type'],['type','Property Type'],['value','Est. Value'],['tags','Lead Tags'],['last','Last Contact'],['status','Status']].map(([key,label])=>({key,label})),visibleColumns=ref(columns.map(c=>c.key)),shownColumns=computed(()=>columns.filter(c=>visibleColumns.value.includes(c.key)));
const filterOptions=[['Absentee Owners','Absentee'],['Vacant Properties','Vacant'],['Probate','Probate'],['Inherited','Inherited'],['Tax Delinquent','Tax Delinquent'],['High Equity','High Equity']].map(([label,value])=>({label,value}));
const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return records.value.filter(r=>(!q||[r.address,r.city,r.owner,...r.tags].join(' ').toLowerCase().includes(q))&&(!applied.value.length||r.tags.some(t=>applied.value.includes(t)))).sort((a,b)=>sort.value==='address'?a.address.localeCompare(b.address):sort.value==='value'?(b.value??-1)-(a.value??-1):sort.value==='last'?b.last.localeCompare(a.last):0);});
const allChecked=computed(()=>filtered.value.length>0&&filtered.value.every(r=>checked.value.includes(r.id))),selectedRecord=computed(()=>records.value.find(r=>r.id===selectedId.value)||null),recordCaption=computed(()=>!imported.value&&county.value==='Duval'&&!applied.value.length&&!query.value?'12,482 verified records':filtered.value.length.toLocaleString()+' records');
const metrics=[['Imported Records','12,482','+12%','database'],['Emails Sent','8,921','+28%','mail'],['SMS Sent','6,314','+34%','text'],['Calls Logged','2,487','+18%','phone'],['Conversations','892','+41%','users'],['Deals from Marketing','68','+31%','handshake'],['Marketing ROI','$27,450','+56%','chart']].map(([label,value,change,icon])=>({label,value,change,icon}));
const campaigns=[['Duval Absentee Owners','3,482','42%','8%',276],['Probate Outreach','1,924','38%','6%',134],['Tax Delinquent','2,156','36%','7%',162],['Vacant Properties','1,842','40%','9%',188],['High Equity Owners','1,078','45%','11%',124]].map(([name,sent,open,reply,leads])=>({name,sent,open,reply,leads}));
