function closeDialog(){dialog.value='';priorFocus?.focus?.();}
function dialogKeys(e){if(e.key==='Escape'){e.preventDefault();closeDialog();}if(e.key==='Tab'){const a=Array.from(dialogEl.value?.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')||[]).filter(n=>!n.disabled);const first=a[0],last=a[a.length-1],active=wwLib.getFrontDocument()?.activeElement;if(e.shiftKey&&(active===first||active===dialogEl.value)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(active===last||active===dialogEl.value)){e.preventDefault();first?.focus();}}}
